# Donor CRM with Campaign and Appeal Tracking

I'll create a comprehensive donor management system with campaign and appeal tracking capabilities.

```python
import streamlit as st
from dataclasses import dataclass, field
from datetime import datetime, timedelta
from typing import List, Dict, Optional
import pandas as pd
from enum import Enum
import json

class DonorType(Enum):
    INDIVIDUAL = "Individual"
    CORPORATE = "Corporate"
    FOUNDATION = "Foundation"
    GOVERNMENT = "Government"

class DonorStatus(Enum):
    ACTIVE = "Active"
    LAPSED = "Lapsed"
    PROSPECT = "Prospect"
    MAJOR = "Major Donor"

class CampaignStatus(Enum:
    PLANNED = "Planned"
    ACTIVE = "Active"
    COMPLETED = "Completed"
    CANCELLED = "Cancelled"

class AppealType(Enum):
    EMAIL = "Email"
    DIRECT_MAIL = "Direct Mail"
    PHONE = "Phone"
    EVENT = "Event"
    SOCIAL_MEDIA = "Social Media"
    ONLINE = "Online"

@dataclass
class Donor:
    id: str
    name: str
    donor_type: DonorType
    status: DonorStatus
    email: str
    phone: str
    address: str
    total_donated: float = 0.0
    first_donation_date: Optional[datetime] = None
    last_donation_date: Optional[datetime] = None
    donation_count: int = 0
    tags: List[str] = field(default_factory=list)
    notes: str = ""

    def update_donation_stats(self, amount: float, date: datetime):
        self.total_donated += amount
        self.donation_count += 1
        if not self.first_donation_date:
            self.first_donation_date = date
        self.last_donation_date = date

        # Update status based on donation history
        if self.total_donated >= 10000:
            self.status = DonorStatus.MAJOR
        elif self.donation_count > 0:
            days_since_last = (datetime.now() - self.last_donation_date).days
            if days_since_last > 365:
                self.status = DonorStatus.LAPSED
            else:
                self.status = DonorStatus.ACTIVE

@dataclass
class Donation:
    id: str
    donor_id: str
    amount: float
    date: datetime
    campaign_id: Optional[str] = None
    appeal_id: Optional[str] = None
    payment_method: str = "Check"
    notes: str = ""
    receipt_sent: bool = False

@dataclass
class Campaign:
    id: str
    name: str
    description: str
    goal: float
    start_date: datetime
    end_date: datetime
    status: CampaignStatus
    total_raised: float = 0.0
    donor_count: int = 0
    appeal_count: int = 0

    def get_progress_percentage(self) -> float:
        if self.goal == 0:
            return 0
        return min((self.total_raised / self.goal) * 100, 100)

    def days_remaining(self) -> int:
        return max(0, (self.end_date - datetime.now()).days)

@dataclass
class Appeal:
    id: str
    campaign_id: str
    name: str
    appeal_type: AppealType
    send_date: datetime
    target_audience: List[str]  # donor tags or segments
    message: str
    total_raised: float = 0.0
    responses: int = 0
    sent_count: int = 0

    def get_response_rate(self) -> float:
        if self.sent_count == 0:
            return 0
        return (self.responses / self.sent_count) * 100

    def get_average_gift(self) -> float:
        if self.responses == 0:
            return 0
        return self.total_raised / self.responses

class DonorCRM:
    def __init__(self):
        self.donors: Dict[str, Donor] = {}
        self.donations: List[Donation] = []
        self.campaigns: Dict[str, Campaign] = {}
        self.appeals: Dict[str, Appeal] = {}

    def add_donor(self, donor: Donor):
        self.donors[donor.id] = donor

    def add_donation(self, donation: Donation):
        self.donations.append(donation)

        # Update donor stats
        if donation.donor_id in self.donors:
            self.donors[donation.donor_id].update_donation_stats(
                donation.amount, donation.date
            )

        # Update campaign stats
        if donation.campaign_id and donation.campaign_id in self.campaigns:
            campaign = self.campaigns[donation.campaign_id]
            campaign.total_raised += donation.amount
            campaign.donor_count = len(set(
                d.donor_id for d in self.donations 
                if d.campaign_id == donation.campaign_id
            ))

        # Update appeal stats
        if donation.appeal_id and donation.appeal_id in self.appeals:
            appeal = self.appeals[donation.appeal_id]
            appeal.total_raised += donation.amount
            appeal.responses += 1

    def add_campaign(self, campaign: Campaign):
        self.campaigns[campaign.id] = campaign

    def add_appeal(self, appeal: Appeal):
        self.appeals[appeal.id] = appeal
        if appeal.campaign_id in self.campaigns:
            self.campaigns[appeal.campaign_id].appeal_count += 1

    def get_donor_giving_history(self, donor_id: str) -> List[Donation]:
        return [d for d in self.donations if d.donor_id == donor_id]

    def get_campaign_donations(self, campaign_id: str) -> List[Donation]:
        return [d for d in self.donations if d.campaign_id == campaign_id]

    def get_appeal_donations(self, appeal_id: str) -> List[Donation]:
        return [d for d in self.donations if d.appeal_id == appeal_id]

    def get_donors_by_tag(self, tag: str) -> List[Donor]:
        return [d for d in self.donors.values() if tag in d.tags]

    def get_lapsed_donors(self, days: int = 365) -> List[Donor]:
        cutoff_date = datetime.now() - timedelta(days=days)
        return [
            d for d in self.donors.values() 
            if d.last_donation_date and d.last_donation_date < cutoff_date
        ]

    def get_top_donors(self, limit: int = 10) -> List[Donor]:
        return sorted(
            self.donors.values(), 
            key=lambda x: x.total_donated, 
            reverse=True
        )[:limit]

